48	
49	  interface IdentityCard {
50	    did: string;
51	    handle: string | null;
52	    pdsUrl: string | null;
53	    deviceKeyIsRoot: boolean | null;
54	    /**
55	     * The Secure Enclave no longer holds this identity's device key (`DEVICE_KEY_UNUSABLE`).
56	     * Distinct from `deviceKeyIsRoot === null`, which only means the custody question could
57	     * not be answered; this is a definite answer — the key is gone.
