62	  let identities = $state<IdentityCard[]>([]);
63	  let didDocs = $state<Map<string, Record<string, unknown>>>(new Map());
64	  let loading = $state(true);
65	  let loadError = $state<string | null>(null);
66	  let alertData = $state<Map<string, UnauthorizedChange[]>>(new Map());
67	  // DIDs eligible for the old-model re-key upgrade (old-model doc OR an interrupted re-key with a
