/**
 * The one label vocabulary the badge and the panel share, so an identity reads the same
 * whichever size it is rendered at.
 *
 * `verified` is a qualifier on the *evidence*, not a fifth state: when the directory could
 * not be reached (`IdentityStatus.checkFailed`), the wallet has no fresh reading, and a
 * panel saying "Secure" would be asserting something it did not check. The identity is not
 * in danger — only our knowledge of it is stale — so it stays in the `safe` state and says
 * so plainly instead.
 */
export function panelLabel(urgency: Urgency, verified: boolean = true): string {
  switch (urgency) {
    case 'safe':
      return verified ? 'Secure' : 'Not checked';
    case 'warning':
      return 'Action needed';
    case 'critical':
      return 'Under attack';
    case 'expired':
      return 'Recovery window closed';
  }
}

/**
 * "Directory checked N ago" for the secure panel.

describe('panelLabel', () => {
  it('uses the shared four-state vocabulary', () => {
    expect(panelLabel('safe')).toBe('Secure');
    expect(panelLabel('warning')).toBe('Action needed');
    expect(panelLabel('critical')).toBe('Under attack');
    expect(panelLabel('expired')).toBe('Recovery window closed');
  });

  it('never claims "Secure" on a reading the wallet could not take', () => {
    expect(panelLabel('safe', false)).toBe('Not checked');
  });

  it('leaves the non-safe states alone — they rest on evidence already in hand', () => {
    // An unreachable directory does not un-detect a change already found, nor revive a
    // device key already known to be gone.
    expect(panelLabel('warning', false)).toBe('Action needed');
    expect(panelLabel('critical', false)).toBe('Under attack');
    expect(panelLabel('expired', false)).toBe('Recovery window closed');
  });
});

